//! GraphQL schema: QueryRoot and MutationRoot are derived from the entity list
//! via `schema_roots!`. Add a new entity in the entities module and in the
//! list below; Queries/Mutations/CustomOperations are generated by the macro.

use std::sync::Arc;

use async_graphql::Schema;
use graphql_orm::schema_roots;

use crate::db::Database;
use crate::services::graphql::entities::*;
use crate::services::graphql::mutations::{
    ArtworkMutations, AuthMutations, FilesystemMutations, LibraryScanMutations,
};
use crate::services::graphql::queries::FilesystemQueries;
use crate::services::graphql::subscriptions::filesystem::FilesystemChangeBroker;
use crate::services::graphql::subscriptions::{FilesystemSubscriptions, TorrentSubscriptions};
use crate::services::manager::ServicesManager;
use crate::services::metadata::providers::{MetadataServiceConfig, create_metadata_service};

schema_roots! {
    query_custom_ops: [User, Torrent, Movie, Show, Album, Audiobook],
    entities: [
        Library,
        Movie,
        Person,
        MovieCastCredit,
        Collection,
        Show,
        Episode,
        MediaFile,
        Artist,
        Album,
        Track,
        Audiobook,
        Chapter,
        Torrent,
        TorrentFile,
        RssFeed,
        RssFeedItem,
        PendingFileMatch,
        Source,
        User,
        InviteToken,
        RefreshToken,
        AppSetting,
        AppLog,
        VideoStream,
        AudioStream,
        Subtitle,
        MediaChapter,
        PlaybackSession,
        PlaybackProgress,
        CastDevice,
        CastSession,
        CastSetting,
        UsenetServer,
        UsenetDownload,
        ScheduleCache,
        ScheduleSyncState,
        NamingPattern,
        MetadataCache,
        SourcePriorityRule,
        Notification,
        ArtworkCache,
        TorznabCategory,
    ],
    extra_query_types: [FilesystemQueries, SourceCustomQueries],
    extra_mutation_types: [ArtworkMutations, AuthMutations, FilesystemMutations, LibraryScanMutations, TorrentClientMutations, MovieMetadataMutations, ShowMetadataMutations, AlbumMetadataMutations, AudiobookMetadataMutations, SourceCustomMutations, CastMutations],
    extra_subscription_types: [FilesystemSubscriptions, TorrentSubscriptions],
}

/// The GraphQL schema type
pub type LibrarianSchema = Schema<QueryRoot, MutationRoot, SubscriptionRoot>;

/// Build the GraphQL schema with all resolvers.
/// Pass the [ServicesManager] so resolvers can obtain the torrent service etc.
pub fn build_schema<E>(
    db: Database,
    auth_service: E,
    services: Arc<ServicesManager>,
) -> LibrarianSchema
where
    E: Send + Sync + Clone + 'static,
{
    // Create MetadataService - it will load API keys from database on demand
    let metadata_service = create_metadata_service(
        db.clone(),
        services.clone(),
        MetadataServiceConfig::default(),
    );

    schema_builder(db)
        .data(auth_service)
        .data(services)
        .data(metadata_service)
        .data(FilesystemChangeBroker::new(64))
        .finish()
}
